  // ---------- 恒星カタログ (Yale Bright Star Catalogue 第5改訂版, V≤6.5, パブリックドメイン) ----------
  // 6バイト/星 [u16 RA·65535/360°, u16 (Dec+90°)·65535/180°, u8 (V+2)·25.5, u8 (B-V+0.5)·85] の
  // リトルエンディアンを base64 パック (約8,400星 ≒ 肉眼で見える全ての星)
  const STAR_B64 = /*STARS*/"";
  // B-V 色指数 → 近似 RGB (青白 → 白 → 黄 → 橙 → 赤)
  function bvColor(bv) {
    const t = Math.max(-0.4, Math.min(2.0, bv));
    if (t < 0.4) { const k = (t + 0.4) / 0.8; return [0.62 + 0.38 * k, 0.75 + 0.25 * k, 1]; }
    if (t < 1.5) { const k = (t - 0.4) / 1.1; return [1, 1 - 0.3 * k, 1 - 0.6 * k]; }
    const k = (t - 1.5) / 0.5;
    return [1, 0.7 - 0.25 * k, 0.4 - 0.25 * k];
  }
  const STAR_RA = [], STAR_SD = [], STAR_CD = [], STAR_MAG = [], STAR_COL = [];
  {
    const bin = atob(STAR_B64);
    for (let o = 0; o + 5 < bin.length; o += 6) {
      const ra = (bin.charCodeAt(o) | bin.charCodeAt(o + 1) << 8) / 65535 * 360 * DEG;
      const dec = ((bin.charCodeAt(o + 2) | bin.charCodeAt(o + 3) << 8) / 65535 * 180 - 90) * DEG;
      STAR_RA.push(ra); STAR_SD.push(Math.sin(dec)); STAR_CD.push(Math.cos(dec));
      STAR_MAG.push(bin.charCodeAt(o + 4) / 25.5 - 2);
      STAR_COL.push(bvColor(bin.charCodeAt(o + 5) / 85 - 0.5));
    }
  }
  const N_CAT = STAR_MAG.length;
  const starGArr = new Float32Array(Math.max(1, N_CAT) * 7);
  let starGVB = null;

  // 宇宙ビュー背景の恒星バッファ (実カタログ: 赤道座標 → 黄道 → ワールド方位)。
  // 星空はカメラ中心の天球として描かれるため、位置 = 方向ベクトル×半径でよい
  {
    const eps = 23.4393 * DEG, ce = Math.cos(eps), se = Math.sin(eps);
    N_STAR = N_CAT;
    const buf = new Float32Array(N_STAR * 7);
    STAR_W = new Float32Array(N_STAR * 3);
    for (let i = 0; i < N_STAR; i++) {
      const xq = STAR_CD[i] * Math.cos(STAR_RA[i]), yq = STAR_CD[i] * Math.sin(STAR_RA[i]), zq = STAR_SD[i];
      const ye = yq * ce + zq * se, ze = -yq * se + zq * ce;   // 赤道 → 黄道
      const o = i * 7, R = 1900, mag = STAR_MAG[i];
      buf[o] = xq * R;              // 黄道 → ワールド (toWorld と同じ軸対応: x, z, -y)
      buf[o + 1] = ze * R;
      buf[o + 2] = -ye * R;
      STAR_W[i*3] = xq; STAR_W[i*3+1] = ze; STAR_W[i*3+2] = -ye;   // ワールド単位方向
      buf[o + 3] = mag < 1.2 ? 2.8 : mag < 2.8 ? 1.9 : mag < 4.0 ? 1.35 : mag < 5.2 ? 1.0 : 0.8;
      const br = Math.min(1, Math.pow(10, -0.11 * mag));       // 等級 → 明るさ
      const col = STAR_COL[i];                                 // B-V 色指数による実際の色味
      buf[o+4] = col[0] * br; buf[o+5] = col[1] * br; buf[o+6] = col[2] * br;
    }
    starVB = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, starVB);
    gl.bufferData(gl.ARRAY_BUFFER, buf, gl.STATIC_DRAW);
  }

