  let constVB = null, constN = 0;      // 宇宙ビュー用: 静的セグメント端点
  const CONST_SEG = [];                // 地上ビュー用: [ra,sinDec,cosDec] ×2 / セグメント
  const CONST_LABELS = [];             // {ja, en, wx, wy, wz, ra, sd, cd}
  {
    const eps = 23.4393 * DEG, ce = Math.cos(eps), se = Math.sin(eps), R = 1895;
    const lines = CONST_JSON ? JSON.parse(CONST_JSON) : {};
    const space = [], a = [0, 0, 0], b = [0, 0, 0];
    const dirW = (raDeg, decDeg, out) => {          // 赤道 → ワールド (x, z, -y)×R
      const ra = raDeg * DEG, dec = decDeg * DEG, cd = Math.cos(dec);
      const xq = cd * Math.cos(ra), yq = cd * Math.sin(ra), zq = Math.sin(dec);
      const ye = yq * ce + zq * se, ze = -yq * se + zq * ce;
      out[0] = xq * R; out[1] = ze * R; out[2] = -ye * R; return out;
    };
    for (const ab in lines) {
      let sx = 0, sy = 0, sz = 0, nv = 0;           // ラベル位置: 赤道単位ベクトルの平均
      const verts = [];                             // 地上ラベル用: ワールド単位方向 [wx,wy,wz]×頂点
      for (const pl of lines[ab]) {
        for (let i = 0; i + 3 < pl.length; i += 2) {
          dirW(pl[i], pl[i + 1], a); dirW(pl[i + 2], pl[i + 3], b);
          space.push(a[0], a[1], a[2], b[0], b[1], b[2]);
          CONST_SEG.push(a[0]/R, a[1]/R, a[2]/R, b[0]/R, b[1]/R, b[2]/R);   // ワールド単位方向×2
        }
        for (let i = 0; i + 1 < pl.length; i += 2) {
          const r = pl[i] * DEG, d = pl[i + 1] * DEG, cd = Math.cos(d);
          sx += cd * Math.cos(r); sy += cd * Math.sin(r); sz += Math.sin(d); nv++;
          dirW(pl[i], pl[i + 1], a); verts.push(a[0]/R, a[1]/R, a[2]/R);
        }
      }
      if (nv) {
        const n = Math.hypot(sx, sy, sz) || 1;
        const xq = sx / n, yq = sy / n, zq = sz / n;
        const nm = CONST_NAME[ab] || [ab, ab];
        // dirW と同じ変換 (赤道 → 黄道 → ワールド)。ye/ze を取り違えると
        // 黄道上の星座名が黄道から外れてしまうので、必ず dirW と揃える
        const ye = yq * ce + zq * se, ze = -yq * se + zq * ce;
        CONST_LABELS.push({
          ja: nm[0], en: nm[1],
          wx: xq * R, wy: ze * R, wz: -ye * R,
          verts,   // 地上ビューは「画面内に見えている頂点の平均位置」に名前を出す
        });
      }
    }
    constN = space.length / 3;
    constVB = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, constVB);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(space), gl.STATIC_DRAW);
  }
